import React, { useState, useEffect, useMemo, Fragment } from 'react';
import { FaInfoCircle, FaPlus, FaTrash, FaPen, FaCheck, FaTimes } from 'react-icons/fa';

// --- Reusable Modal Component ---
const Modal = ({ show, onClose, title, children }) => {
    if (!show) {
        return null;
    }
    return (
        <div style={styles.modalBackdrop}>
            <div style={styles.modalContent}>
                <div style={styles.modalHeader}>
                    <h4 style={styles.modalTitle}>{title}</h4>
                    <button onClick={onClose} style={styles.closeButton}>&times;</button>
                </div>
                <div style={styles.modalBody}>
                    {children}
                </div>
                <div style={styles.modalFooter}>
                    <button onClick={onClose} style={styles.buttonSecondary}>Close</button>
                </div>
            </div>
        </div>
    );
};

// --- Main Component ---
export default function PerDeliveryAllocationTab({ term, onAllocationChange }) {
    // --- State Management ---
    const [firstOffering, setFirstOffering] = useState('Yes');
    const [deliveries, setDeliveries] = useState([
        { id: 1, location: 'CTN', lecturer: 'Mary', weeklyHours: 2, earlyCareer: 'No' },
        { id: 2, location: 'PEN', lecturer: 'Mary', weeklyHours: 0, earlyCareer: 'No' },
        { id: 3, location: 'KWD', lecturer: 'Mary', weeklyHours: 0, earlyCareer: 'No' },
    ]);

    const [editingId, setEditingId] = useState(null);
    const [editFormData, setEditFormData] = useState({});
    const [errors, setErrors] = useState({});
    const [modalContent, setModalContent] = useState({ show: false, title: '', content: '' });
    const [deleteConfirm, setDeleteConfirm] = useState({ show: false, id: null });

    // --- Calculation Logic ---
    const termMultiplier = useMemo(() => (term === 'Autumn' ? 1.0 : 0.923), [term]);

    const getIndividualAllocation = (delivery) => {
        const earlyCareerBonusMap = {
            "Yes - materials provided": 0.02,
            "Yes - materials need major rewriting": 0.03,
            "Yes - no materials provided": 0.04,
        };
        const hours = Number(delivery.weeklyHours) || 0;
        const earlyCareerBonus = earlyCareerBonusMap[delivery.earlyCareer] || 0;
        return 0.01 + (hours * termMultiplier * 0.01) + earlyCareerBonus;
    };

    useEffect(() => {
        const sumOfIndividualAllocations = deliveries.reduce((sum, d) => sum + getIndividualAllocation(d), 0);

        let firstOfferingBonus = 0;
        if (firstOffering === 'Yes' && deliveries.length > 0) {
            const maxWeeklyHours = Math.max(...deliveries.map(d => Number(d.weeklyHours) || 0));
            firstOfferingBonus = 0.01 * termMultiplier * maxWeeklyHours;
        }

        const finalTotal = sumOfIndividualAllocations + firstOfferingBonus;
        if (onAllocationChange) {
            onAllocationChange(finalTotal);
        }
    }, [deliveries, firstOffering, termMultiplier, onAllocationChange, getIndividualAllocation]);

    // --- Validation ---
    const validate = (data) => {
        const newErrors = {};
        const nameRegex = /^[a-zA-Z\s]+$/;

        if (!data.location || !data.location.trim()) newErrors.location = "Delivery location cannot be empty.";
        else if (!nameRegex.test(data.location)) newErrors.location = "Invalid Delivery! Cannot have numbers or special characters.";

        if (!data.lecturer || !data.lecturer.trim()) newErrors.lecturer = "Lecturer cannot be empty.";
        else if (!nameRegex.test(data.lecturer)) newErrors.lecturer = "Invalid Lecturer! Cannot have numbers or special characters.";

        const hours = data.weeklyHours;
        if (hours === '' || hours === null || isNaN(hours)) newErrors.weeklyHours = "Incorrect hours! Must be a number.";
        else if (Number(hours) < 0) newErrors.weeklyHours = "Incorrect hours! Cannot be negative.";

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    // --- Handlers for CRUD and UI ---
    const handleEditClick = (delivery) => {
        setEditingId(delivery.id);
        setEditFormData(delivery);
        setErrors({});
    };

    const handleCancelClick = () => {
        setEditingId(null);
        setErrors({});
    };

    const handleAddClick = () => {
        const newId = deliveries.length > 0 ? Math.max(...deliveries.map(d => d.id)) + 1 : 1;
        const newEntry = { id: newId, location: '', lecturer: '', weeklyHours: 0, earlyCareer: 'No' };
        setEditFormData(newEntry);
        setEditingId(newId);
        setDeliveries([...deliveries, newEntry]); // Add temporary row
        setErrors({});
    };

    const handleFormChange = (e) => {
        const { name, value } = e.target;
        setEditFormData({ ...editFormData, [name]: value });
    };

    const handleSaveClick = (id) => {
        if (!validate(editFormData)) return;

        const updatedDeliveries = deliveries.map(d => (d.id === id ? editFormData : d));
        setDeliveries(updatedDeliveries);
        setEditingId(null);
        alert("Record saved successfully!");
    };

    const handleDeleteClick = (id) => {
        setDeleteConfirm({ show: true, id: id });
    };

    const confirmDelete = () => {
        setDeliveries(deliveries.filter(d => d.id !== deleteConfirm.id));
        setDeleteConfirm({ show: false, id: null });
    };

    const handleShowInfo = (type) => {
        if (type === 'main') {
            setModalContent({
                show: true,
                title: 'Per-delivery Allocation Information',
                content: "The per-delivery allocation covers tasks at the large group level: (i) preparation of teaching materials for lectures or large group workshops [first delivery in each calendar year only]; (ii) lecture or large workshop delivery; (iii) subject coordination tasks that depend only on the number of deliveries, for instance, timetabling matters or campus coordination of lecturers and tutors; and (iv) any other matters arising from delivering the subject for a separate student cohort."
            });
        } else {
            setModalContent({
                show: true,
                title: 'First Offering Information',
                content: `List all deliveries and, for each delivery, indicate the lecturer, the weekly lecture (or large group class) time, and whether the lecturing staff member is an early career academic; see the SCDMS Work Plan Policy or the notes (tool tips) for the definition of “delivery”, “early career academic” and “weekly lecture time”.\n\nThe "weekly lecture time" is based on the average weekly large group classes (such as lectures) over the entire term; other arrangements such as fortnightly classes should be counted pro-rata.\n\nWhere an external delivery or a blended delivery in which all content is delivered through vUWS is the only delivery of the subject in the given term, that delivery is considered to be equivalent to a 1 hour lecture per week.\n\nIn all other situations, large group classes are counted as they are actually taught.\n\n- For a subject that has an external or blended delivery in Edition to a live delivery (on campus or via Zoom), the external or blended delivery should be entered with a weekly lecture time of 0 hours.\n\n- For a subject that has live lectures taught across multiple campuses via Zoom, one delivery should be entered normally; the remaining deliveries should be entered with a weekly lecture time of 0 hours.`
            });
        }
    };

    // Total calculation for display
    const totalAllocation = useMemo(() => {
         const sumOfIndividualAllocations = deliveries.reduce((sum, d) => sum + getIndividualAllocation(d), 0);
        let firstOfferingBonus = 0;
        if (firstOffering === 'Yes' && deliveries.length > 0) {
            const maxWeeklyHours = Math.max(...deliveries.map(d => Number(d.weeklyHours) || 0));
            firstOfferingBonus = 0.01 * termMultiplier * maxWeeklyHours;
        }
        return sumOfIndividualAllocations + firstOfferingBonus;
    }, [deliveries, firstOffering, termMultiplier, getIndividualAllocation]);


    return (
        <div style={styles.container}>
            <Modal 
                show={modalContent.show} 
                onClose={() => setModalContent({ ...modalContent, show: false })} 
                title={modalContent.title}
            >
                <p style={{ whiteSpace: 'pre-wrap' }}>{modalContent.content}</p>
            </Modal>
            <Modal
                show={deleteConfirm.show}
                onClose={() => setDeleteConfirm({ show: false, id: null })}
                title="Confirm Deletion"
            >
                <p>Are you sure you want to delete this record?</p>
                <div style={{...styles.modalFooter, justifyContent: 'flex-end'}}>
                     <button onClick={() => setDeleteConfirm({ show: false, id: null })} style={styles.buttonSecondary}>Cancel</button>
                     <button onClick={confirmDelete} style={{...styles.buttonPrimary, marginLeft: '1rem', backgroundColor: '#dc3545' }}>Confirm</button>
                </div>
            </Modal>

            <div style={styles.formGroup}>
                <label style={styles.label}>
                    Per-delivery Allocation
                    <button onClick={() => handleShowInfo('main')} style={styles.infoButton}><FaInfoCircle /></button>
                </label>
                <input type="text" value={`${(totalAllocation * 100).toFixed(1)}%`} readOnly style={styles.inputReadOnly} />
            </div>

            <div style={styles.formGroup}>
                <label htmlFor="firstOffering" style={styles.label}>
                    First offering of the calendar year
                    <button onClick={() => handleShowInfo('firstOffering')} style={styles.infoButton}><FaInfoCircle /></button>
                </label>
                <select id="firstOffering" value={firstOffering} onChange={(e) => setFirstOffering(e.target.value)} style={styles.select}>
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                </select>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '1rem' }}>
                <button onClick={handleAddClick} style={styles.addButton} disabled={editingId !== null}>
                    <FaPlus style={{ marginRight: '8px' }}/> Add
                </button>
            </div>

            <form onSubmit={(e) => e.preventDefault()}>
                <table style={styles.table}>
                    <thead>
                        <tr>
                            <th style={styles.th}>Actions</th>
                            <th style={styles.th}>Delivery</th>
                            <th style={styles.th}>Lecturer / Campus Coordinator</th>
                            <th style={styles.th}>Weekly lecture time (hours)</th>
                            <th style={styles.th}>Early career academic loading</th>
                            <th style={styles.th}>Allocation</th>
                        </tr>
                    </thead>
                    <tbody>
                        {deliveries.map(delivery => (
                            <Fragment key={delivery.id}>
                                {editingId === delivery.id ? (
                                    // --- Editable Row ---
                                    <tr>
                                        <td style={styles.td}>
                                            <button type="button" onClick={() => handleSaveClick(delivery.id)} style={styles.iconButton}><FaCheck color="green" /></button>
                                            <button type="button" onClick={handleCancelClick} style={styles.iconButton}><FaTimes color="red" /></button>
                                        </td>
                                        <td style={styles.td}>
                                            <input type="text" name="location" value={editFormData.location} onChange={handleFormChange} style={{...styles.tableInput, borderColor: errors.location ? 'red' : '#ced4da'}} />
                                            {errors.location && <small style={styles.errorText}>{errors.location}</small>}
                                        </td>
                                        <td style={styles.td}>
                                            <input type="text" name="lecturer" value={editFormData.lecturer} onChange={handleFormChange} style={{...styles.tableInput, borderColor: errors.lecturer ? 'red' : '#ced4da'}} />
                                            {errors.lecturer && <small style={styles.errorText}>{errors.lecturer}</small>}
                                        </td>
                                        <td style={styles.td}>
                                            <input type="number" name="weeklyHours" value={editFormData.weeklyHours} onChange={handleFormChange} style={{...styles.tableInput, borderColor: errors.weeklyHours ? 'red' : '#ced4da'}} />
                                             {errors.weeklyHours && <small style={styles.errorText}>{errors.weeklyHours}</small>}
                                        </td>
                                        <td style={styles.td}>
                                            <select name="earlyCareer" value={editFormData.earlyCareer} onChange={handleFormChange} style={styles.tableSelect}>
                                                <option>No</option>
                                                <option>Yes - materials provided</option>
                                                <option>Yes - materials need major rewriting</option>
                                                <option>Yes - no materials provided</option>
                                            </select>
                                        </td>
                                        <td style={styles.td}>
                                            <input type="text" value={`${(getIndividualAllocation(editFormData) * 100).toFixed(1)}%`} readOnly style={{...styles.tableInput, ...styles.inputReadOnly, textAlign: 'right' }} />
                                        </td>
                                    </tr>
                                ) : (
                                    // --- Read-Only Row ---
                                    <tr>
                                        <td style={styles.td}>
                                            <button type="button" onClick={() => handleEditClick(delivery)} style={styles.iconButton} disabled={editingId !== null}><FaPen /></button>
                                            <button type="button" onClick={() => handleDeleteClick(delivery.id)} style={styles.iconButton} disabled={editingId !== null}><FaTrash /></button>
                                        </td>
                                        <td style={styles.td}>{delivery.location}</td>
                                        <td style={styles.td}>{delivery.lecturer}</td>
                                        <td style={styles.td}>{delivery.weeklyHours}</td>
                                        <td style={styles.td}>{delivery.earlyCareer}</td>
                                        <td style={{...styles.td, textAlign: 'right'}}>{`${(getIndividualAllocation(delivery) * 100).toFixed(1)}%`}</td>
                                    </tr>
                                )}
                            </Fragment>
                        ))}
                    </tbody>
                </table>
            </form>
        </div>
    );
}

// --- Component-Specific Styles ---
const styles = {
    container: { padding: '2rem', backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #dee2e6' },
    formGroup: { marginBottom: '1.5rem' },
    label: { display: 'flex', alignItems: 'center', fontWeight: '500', color: '#343a40', marginBottom: '0.5rem' },
    inputReadOnly: { width: '150px', padding: '0.5rem', border: '1px solid #ced4da', borderRadius: '4px', backgroundColor: '#e9ecef', color: '#495057', fontWeight: 'bold' },
    select: { width: '200px', padding: '0.5rem', border: '1px solid #ced4da', borderRadius: '4px', backgroundColor: '#fff' },
    addButton: { padding: '0.5rem 1.5rem', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold', display: 'flex', alignItems: 'center' },
    table: { width: '100%', borderCollapse: 'collapse', marginTop: '1rem' },
    th: { backgroundColor: '#f8f9fa', border: '1px solid #dee2e6', padding: '0.75rem', textAlign: 'left', fontWeight: '600', color: '#495057', fontSize: '0.9rem' },
    td: { border: '1px solid #dee2e6', padding: '0.5rem', verticalAlign: 'top' },
    tableInput: { width: '100%', padding: '0.5rem', border: '1px solid #ced4da', borderRadius: '4px', boxSizing: 'border-box' },
    tableSelect: { width: '100%', padding: '0.5rem', border: '1px solid #ced4da', borderRadius: '4px', boxSizing: 'border-box', backgroundColor: '#fff' },
    iconButton: { background: 'none', border: 'none', cursor: 'pointer', padding: '0.5rem', color: '#6c757d' },
    infoButton: { background: 'none', border: 'none', cursor: 'pointer', color: '#007bff', marginLeft: '8px' },
    errorText: { color: 'red', fontSize: '0.8rem', marginTop: '4px' },
    // Modal Styles
    modalBackdrop: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
    modalContent: { backgroundColor: 'white', padding: '20px', borderRadius: '8px', width: '500px', maxWidth: '90%', boxShadow: '0 5px 15px rgba(0,0,0,0.3)' },
    modalHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #dee2e6', paddingBottom: '10px' },
    modalTitle: { margin: 0, fontSize: '1.25rem' },
    closeButton: { background: 'none', border: 'none', fontSize: '1.5rem', cursor: 'pointer' },
    modalBody: { paddingTop: '10px', maxHeight: '60vh', overflowY: 'auto' },
    modalFooter: { borderTop: '1px solid #dee2e6', paddingTop: '10px', marginTop: '10px', display: 'flex', justifyContent: 'flex-end' },
    buttonPrimary: { padding: '0.6rem 1.2rem', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: '500' },
    buttonSecondary: { padding: '0.6rem 1.2rem', backgroundColor: '#6c757d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: '500' },
};
